function integer(x,min,max){const n=Number(x);if(!Number.isInteger(n)||n<min||n>max)throw Error('Enter a whole number from '+min+' to '+max+'.');return n;}
function ip(s){const p=String(s||'').trim().split('.');if(p.length!==4||!p.every(x=>/^(0|[1-9]\d{0,2})$/.test(x)&&Number(x)<=255))throw Error('Enter a valid IPv4 address.');return p.reduce((a,x)=>(a<<8n)+BigInt(x),0n);}
